import type { Argv, ArgumentsCamelCase } from 'yargs'
import { cwd } from 'process'
import { logger } from '../../logger'
import * as fs from 'fs'
import { createTelemetryClient } from '../../telemetry'
import { credentialProvider } from '../../auth'
import { Project, Orchestrator } from '@servicenow/sdk-api'
import { validateWorkingDir } from '../../util'
import { withProfiling } from '../../util/profiler'
import { NowConfig, type Telemetry } from '@servicenow/sdk-build-core'

type TransformArguments = {
    directory: string
    from?: string
    preview?: boolean
    mode?: 'incremental' | 'complete' | undefined
    credentials?: unknown
    auth?: string
    format?: boolean
    id?: string
    table?: string
    updateSet?: string
    maxUpdateCount?: number
    ids?: string[]
    profile: boolean
}

export function builder(yargs: Argv) {
    return yargs
        .option('from', {
            describe: 'Path to local XML file(s)/directory to transform',
            type: 'string',
        })
        .option('directory', {
            describe: `Path to the directory that contains package.json configuration`,
            default: cwd(),
            type: 'string',
        })
        .option('mode', {
            describe:
                'Application fetch mode,\n\n' +
                'complete:\n Download and extract the complete application.\n\n' +
                'incremental:\n Download changes with a corresponding Customer Update (sys_update_xml) record.',
            choices: ['complete', 'incremental'],
            type: 'string',
            coerce: (arg) => arg.toLowerCase(),
            alias: 'm',
            hidden: true,
        })
        .option('auth', {
            describe: 'Credential alias to use for authentication with instance',
            type: 'string',
            alias: 'a',
        })
        .option('format', {
            describe: 'Automatically format new and updated source code after transforming.',
            type: 'boolean',
            alias: 'f',
            default: true,
        })
        .option('id', {
            describe: 'Sys ID of the Metadata to transform with relationships (requires --table)',
            type: 'string',
            hidden: true,
        })
        .option('table', {
            describe:
                'Comma-separated table names to transform by table hierarchy. ' +
                'When used with --id, transforms a specific record with its relationships.',
            type: 'string',
        })
        .option('updateSet', {
            describe: 'sysId of update set to transform from',
            type: 'string',
            hidden: true,
        })
        .option('maxUpdateCount', {
            describe: 'Upper limit of number of records to transform from an update set',
            type: 'number',
            hidden: true,
        })
        .option('ids', {
            describe: 'Sys IDs of the Metadata to transform',
            type: 'array',
            hidden: true,
        })
        .option('profile', {
            describe: 'Profile transform and output a .cpuprofile file',
            type: 'boolean',
            default: false,
            hidden: true,
        })
        .check((args) => {
            // --id requires --table (but --table can be used alone for table-based transform)
            if (args.id && !args.table) {
                throw new Error('--id requires --table')
            }
            return true
        })
        .conflicts('from', ['mode', 'auth'])
        .conflicts('ids', ['id', 'table'])
        .conflicts('id', ['from', 'mode', 'updateSet', 'ids'])
        .conflicts('table', ['updateSet', 'ids']) as any
}

export async function handler(args: ArgumentsCamelCase<TransformArguments>): Promise<void> {
    await withProfiling(args.profile, 'transform', fs, async () => {
        let telemetryClient: Telemetry | undefined
        try {
            // Offline mode: --from flag transforms local XML files without needing credentials
            const isOfflineMode = !!args.from
            let credential: Awaited<ReturnType<typeof credentialProvider>> | undefined

            if (!isOfflineMode) {
                // Online mode requires credentials to fetch from instance
                credential = await credentialProvider(args.auth)
                telemetryClient = createTelemetryClient(__dirname, credential.getUrl())
            } else {
                telemetryClient = createTelemetryClient(__dirname)
            }

            const workingDir = validateWorkingDir(args.directory)
            const config = NowConfig.parseFromDirectory(workingDir, fs, logger)
            const project = new Project({ config, fileSystem: fs, rootDir: workingDir, logger, telemetryClient })
            const orchestrator = new Orchestrator(project, credential)

            const options = args.updateSet
                ? {
                      format: args.format ?? true,
                      method: 'update-set' as const,
                      updateSetId: args.updateSet,
                      maxUpdateCount: args.maxUpdateCount,
                  }
                : {
                      format: args.format ?? true,
                      // --table without --id: table-based chunked transform
                      // --table with --id: specific record with relationships (existing BA behavior)
                      ...(args.table && !args.id ? { tables: args.table.split(',').map((t) => t.trim()) } : {}),
                      ...(args.from ? { paths: [args.from] } : args.mode ? { method: args.mode } : undefined),
                      ...(args.id ? { sysId: args.id } : undefined),
                      ...(args.table && args.id ? { table: args.table } : undefined),
                      ...(args.ids ? { sysIds: args.ids } : undefined),
                  }

            await orchestrator.transform(options)

            logger.info('Transform completed successfully')
        } catch (error) {
            logger.error('Transform failed.', error)
            logger.info('For more detailed debug output, try running the command again with the "-d" option')
            process.exitCode = 1
        }
    })
}
